function database(): PDO { $db = new PDO('sqlite::memory:'); $db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC); return $db; }
$directory = sys_get_temp_dir() . '/pk-staff-' . bin2hex(random_bytes(12)); mkdir($directory, 0700);
