    $scopedDb=database();$scoped=new Staff($scopedDb,$keys,$directory.'/scoped.enc',true,'pk_fixture_123456abcdef_');$scoped->migrate();$scoped->insertFixture(['childName'=>'SCOPED FICTIONAL FIXTURE'],[],[],$now);
