    denied(fn () => $app->detail('', $id, $now), 'direct record authentication enforced');
    ok(count($app->listing($token, $now)) === 1, 'bounded admin listing works');
    $r = $app->detail($token, $id, $now); ok($r['care']['healthNotes'] === 'SYNTHETIC-HEALTH-DO-NOT-LOG', 'authorized care decryption');
    $raw = $db->query('SELECT org,care,proofs FROM pk_staff_requests')->fetch();
    ok(!str_contains(json_encode($raw), 'SYNTHETIC-HEALTH') && !str_contains(json_encode($raw), 'FIKTIVES'), 'database categories encrypted');
    $swap=$db->prepare('UPDATE pk_staff_requests SET care=? WHERE id=?');$swap->execute([$raw['org'],$id]);
    denied(fn()=>$app->detail($token,$id,$now),'ciphertext cannot be moved into another category');
    $swap->execute([$raw['care'],$id]);
    $other=$app->insertFixture(['childName'=>'CIPHERTEXT BINDING FIXTURE'],[],[],$now);
    $otherOrg=$db->query("SELECT org FROM pk_staff_requests WHERE id='$other'")->fetchColumn();$move=$db->prepare('UPDATE pk_staff_requests SET org=? WHERE id=?');$move->execute([$raw['org'],$other]);
    denied(fn()=>$app->detail($token,$other,$now),'ciphertext cannot be moved to another record');$move->execute([$otherOrg,$other]);
    $backup = $app->backup($now); ok(!str_contains($backup,'fixture@example.invalid') && !str_contains($backup,$password), 'backup contains neither plaintext participant data nor passwords');
