    denied(fn ()=>$app->change($token,$app->csrf($token),$id,1,'confirmed',['confirmedOutside'=>'yes'],$now),'write outage never reports successful state change');
    $db->exec('DROP TRIGGER fixture_failure');ok($app->detail($token,$id,$now)['status']==='pending','write failure rolls state back');
