    $restoredDb = database(); $restored = new Staff($restoredDb,$keys,$journal,true); $restored->migrate(); $restored->setAdmin('fixture-admin',$password);
    $restorePre=$restored->newSession($now+2); $beforeRestore=$restored->login($restorePre,$restored->csrf($restorePre),'fixture-admin',$password,'127.0.0.1',$now+2);
    $restored->restore($backup,$now+3);
    ok($restored->session($beforeRestore,$now+3)===null,'restore invalidates sessions');
    $rp=$restored->newSession($now+3);$rt=$restored->login($rp,$restored->csrf($rp),'fixture-admin',$password,'127.0.0.1',$now+3);
    $rr=$restored->detail($rt,$id,$now+3);
    ok(!isset($rr['care']['healthNotes']),'restored old backup cannot resurrect withdrawn health notes');
    ok(isset($rr['proofs']['website']['withdrawnAt']),'restored old backup cannot resurrect media permission');
    ok($rr['status']==='reconciliation','restored status never silently confirms a place');
    $proofId=$app->insertFixture(['childName'=>'PROOF EXPIRY FIXTURE'],[],['health'=>['version'=>'fixture','due'=>$now-1],'website'=>['version'=>'fixture','grantedAt'=>$now]],$now);
    $proofView=$app->detail($token,$proofId,$now);
    ok(!isset($proofView['proofs']['health'])&&isset($proofView['proofs']['website']),'proofs expire independently by purpose');
    $app->retention($now);
    denied(fn ()=>$restored->restore($backup,$now+4),'restore refuses nonempty target');
    denied(fn ()=>$restored->restore(substr($backup,0,-8).'abcdefgh',$now+4),'tampered backup rejected');
    $empty = new Staff(database(),$keys,$journal,true);$empty->migrate();
    denied(fn ()=>$empty->restore($backup,$now+36*86400),'over-age backup rejected');
    $app->change($token,$app->csrf($token),$id,3,'rejected',[],$now+3);
    ok($app->detail($token,$id,$now+3)['care']===null,'rejected request care data removed immediately');
    $deadlineDb=database();$deadlineRestore=new Staff($deadlineDb,$keys,$journal,true);$deadlineRestore->migrate();$deadlineRestore->restore($backup,$now+4);
    ok((int)$deadlineDb->query('SELECT org_due FROM pk_staff_requests')->fetchColumn()<=$now+90*86400+3,'restoration replays stricter closure deadlines');
    $app->retention($now+91*86400);
    $later=$app->newSession($now+91*86400);$lt=$app->login($later,$app->csrf($later),'fixture-admin',$password,'127.0.0.1',$now+91*86400);
    ok($app->detail($lt,$id,$now+91*86400)['org']===null,'organizational data removed after 90 days');
    $id2=$app->insertFixture(['childName'=>'SECOND SYNTHETIC CHILD'],['healthNotes'=>'SECOND SYNTHETIC HEALTH'],[],$now);
    $app->change($lt,$app->csrf($lt),$id2,1,'confirmed',['confirmedOutside'=>'yes'],$now+91*86400);
    $app->change($lt,$app->csrf($lt),$id2,2,'completed',['lastTrainingAt'=>$now+90*86400],$now+91*86400);
    $day105=$now+105*86400;$n=$app->newSession($day105);$nt=$app->login($n,$app->csrf($n),'fixture-admin',$password,'127.0.0.1',$day105);
    ok($app->detail($nt,$id2,$day105)['care']===null,'expired care hidden even before cron');
    denied(fn ()=>$app->change($nt,$app->csrf($nt),$id2,3,'hold',['until'=>$day105+86400,'basis'=>'Specific synthetic legal reason','categories'=>['care'],'specialBasis'=>'yes'],$day105),'late hold cannot resurrect expired content');
    $app->retention($day105);ok($db->query("SELECT care FROM pk_staff_requests WHERE id='$id2'")->fetchColumn()===null,'14-day care purge persisted');
    $id3=$app->insertFixture(['childName'=>'HELD SYNTHETIC CHILD'],['healthNotes'=>'HELD SYNTHETIC HEALTH'],[],$day105);
    denied(fn ()=>$app->change($nt,$app->csrf($nt),$id3,1,'hold',['until'=>$day105+86400,'basis'=>'Specific synthetic documented reason','categories'=>['care']],$day105),'health hold needs special-category basis');
    denied(fn ()=>$app->change($nt,$app->csrf($nt),$id3,1,'hold',['until'=>$day105+32*86400,'basis'=>'Specific synthetic documented reason','categories'=>['org']],$day105),'hold requires monthly review');
    $app->change($nt,$app->csrf($nt),$id3,1,'hold',['until'=>$day105+86400,'basis'=>'Specific synthetic documented legal reason','categories'=>['care'],'specialBasis'=>'yes'],$day105);
    $app->change($nt,$app->csrf($nt),$id3,2,'rejected',[],$day105);
    ok($app->detail($nt,$id3,$day105)['care']!==null,'narrow active hold respected');
    $afterHold=$day105+2*86400;$n=$app->newSession($afterHold);$nt=$app->login($n,$app->csrf($n),'fixture-admin',$password,'127.0.0.1',$afterHold);
