    denied(fn ()=>$app->detail($nt,$id,$afterHold),'revoked user loses stale session access');
    $app->setAdmin('fixture-admin',$password);$n=$app->newSession($afterHold);$nt=$app->login($n,$app->csrf($n),'fixture-admin',$password,'127.0.0.1',$afterHold);
    $app->logout($nt);denied(fn ()=>$app->requireAdmin($nt,$afterHold),'sign-out invalidates session');
    $n=$app->newSession($afterHold);$nt=$app->login($n,$app->csrf($n),'fixture-admin',$password,'127.0.0.1',$afterHold);
    ok($app->session($nt,$afterHold+1200)===null,'idle timeout enforced');
    $db->exec("UPDATE pk_staff_users SET role='coach'");$n=$app->newSession($afterHold);
    denied(fn ()=>$app->login($n,$app->csrf($n),'fixture-admin',$password,'127.0.0.1',$afterHold),'unimplemented coach access fails closed');
    $app->setAdmin('fixture-admin',$password);$n=$app->newSession($afterHold);
    for($i=0;$i<10;$i++)denied(fn ()=>$app->login($n,$app->csrf($n),'fixture-admin','wrong-password','untrusted-peer',$afterHold),'failed login bounded');
    denied(fn ()=>$app->login($n,$app->csrf($n),'FIXTURE-ADMIN',$password,'different-peer',$afterHold),'account throttle survives changed peer and identifier case');
    $audit=json_encode($db->query('SELECT * FROM pk_staff_audit')->fetchAll());
    ok(!str_contains($audit,'SYNTHETIC')&&!str_contains($audit,'fixture@example.invalid')&&!str_contains($audit,$password),'audit contains no form values or passwords');
    ok(!str_contains(file_get_contents($journal),'SYNTHETIC'),'independent erasure journal encrypted');
    $app->retention($afterHold+100*86400);ok((int)$db->query('SELECT COUNT(*) FROM pk_staff_audit')->fetchColumn()<5,'old audit records expire');
    putenv('PK_STAFF_CONFIG=');putenv('PK_STAFF_LIBRARY=');$_SERVER['DOCUMENT_ROOT']=realpath(__DIR__.'/../staff/public');ob_start();require __DIR__.'/../staff/public/index.php';$unavailable=ob_get_clean();
    ok(http_response_code()===503&&$unavailable==='Die Anmeldungsverwaltung ist noch nicht freigegeben.','public candidate entry fails closed without private setup');
    echo json_encode(['passed'=>true,'checks'=>$checks,'storage'=>'SQLite fixtures only','mariaDbAccepted'=>false,'publicIntakeEnabled'=>false],JSON_THROW_ON_ERROR)."\n";
} finally {
    foreach (glob($directory.'/*') as $file) unlink($file);rmdir($directory);
